function dcim_connected_device_list() {
  var url = "/api/dcim/connected-device/";
  var reqDescription = "This endpoint allows a user to determine what device (if any) is connected to a given peer device and peer interface. {id}";
  return svc.get(url, { parameters: { description: reqDescription }, expectedResponseCodes: [200] });
}

function verifyConnectedDeviceExists(id, peer_device, peer_interface) {
  // Fallback: Use list operation to verify existence
  let res = dcim_connected_device_list(id, peer_device, peer_interface);
  try {
      let listData = res;
      if (typeof listData === "string") listData = JSON.parse(listData);
      if (!Array.isArray(listData) && listData.data) listData = listData.data;
      if (Array.isArray(listData)) {
          let found = listData.find(item => item.id == id || item.id == id);
          if (found) pvg.success("ConnectedDevice found in list");
          else pvg.fail("ConnectedDevice NOT found in list");
      }
  } catch (err) { bp.log.warn("Failed to parse list response: " + err); }
}

function verifyConnectedDeviceDeleted(id, peer_device, peer_interface) {
  // Fallback: Use list operation to verify deletion
  let res = dcim_connected_device_list(id, peer_device, peer_interface);
  try {
      let listData = res;
      if (typeof listData === "string") listData = JSON.parse(listData);
      if (!Array.isArray(listData) && listData.data) listData = listData.data;
      if (Array.isArray(listData)) {
          let found = listData.find(item => item.id == id || item.id == id);
          if (!found) pvg.success("ConnectedDevice correctly not found in list");
          else pvg.fail("ConnectedDevice still found in list (deletion failed)");
      }
  } catch (err) { bp.log.warn("Failed to parse list response: " + err); }
}

function verifyConnectedDeviceDoesNotExist(id, peer_device, peer_interface) { verifyConnectedDeviceDeleted(id, peer_device, peer_interface); }

function matchAnyConnectedDeviceAdded() {
  return bp.EventSet("Any ConnectedDevice Added", function(e) {
      return e.name.startsWith("Done: Positive: Create ConnectedDevice");
  });
}

