function dcim_console_ports_destroy(id) {
  var url = "/api/dcim/console-ports/" + id + "/";
  var reqDescription = "Delete a console port object. " + id;
  let res = svc.delete(url, { parameters: { description: reqDescription }, expectedResponseCodes: [200, 204] });
  if (res.status >= 200 && res.status < 300) {
    bp.sync({ request: bp.Event("Done: Positive: " + reqDescription) });
  }
  return res;
}

function dcim_console_ports_retrieve(id) {
  var url = "/api/dcim/console-ports/" + id + "/";
  var reqDescription = "Get a console port object. " + id;
  return svc.get(url, { parameters: { description: reqDescription }, expectedResponseCodes: [200] });
}

function dcim_console_ports_update(custom_fields, description, device, id, label, mark_connected, module, name, speed, tags, type) {
  var url = "/api/dcim/console-ports/" + id + "/";
  var reqDescription = "Put a console port object. " + id;
  var body = {
    "custom_fields": custom_fields,
    "description": String(description),
    "device": String(device),
    "label": String(label),
    "mark_connected": mark_connected,
    "module": String(module),
    "name": String(name),
    "speed": speed,
    "tags": tags,
    "type": String(type),
};
  bp.log.info("REQ PUT " + url + " Body: " + JSON.stringify(body));
  let res = svc.put(url, { body: JSON.stringify(body), expectedResponseCodes: [200], parameters: { description: reqDescription } });
  if (res.status >= 200 && res.status < 300) {
    bp.sync({ request: bp.Event("Done: Positive: " + reqDescription, {"custom_fields": custom_fields, "description": description, "device": device, "id": id, "label": label, "mark_connected": mark_connected, "module": module, "name": name, "speed": speed, "tags": tags, "type": type}) });
  }
  return res;
}

