function dcim_front_port_templates_bulk_destroy() {
  var url = "/api/dcim/front-port-templates/";
  var reqDescription = "Delete a list of front port template objects. {id}";
  let res = svc.delete(url, { parameters: { description: reqDescription }, expectedResponseCodes: [200, 204] });
  if (res.status >= 200 && res.status < 300) {
    bp.sync({ request: bp.Event("Done: Positive: " + reqDescription) });
  }
  return res;
}

