function dcim_power_ports_destroy(id) {
  var url = "/api/dcim/power-ports/" + id + "/";
  var reqDescription = "Delete a power port object. " + id;
  let res = svc.delete(url, { parameters: { description: reqDescription }, expectedResponseCodes: [200, 204] });
  if (res.status >= 200 && res.status < 300) {
    bp.sync({ request: bp.Event("Done: Positive: " + reqDescription) });
  }
  return res;
}

function dcim_power_ports_retrieve(id) {
  var url = "/api/dcim/power-ports/" + id + "/";
  var reqDescription = "Get a power port object. " + id;
  return svc.get(url, { parameters: { description: reqDescription }, expectedResponseCodes: [200] });
}

function dcim_power_ports_update(allocated_draw, custom_fields, description, device, id, label, mark_connected, maximum_draw, module, name, tags, type) {
  var url = "/api/dcim/power-ports/" + id + "/";
  var reqDescription = "Put a power port object. " + id;
  var body = {
    "allocated_draw": allocated_draw,
    "custom_fields": custom_fields,
    "description": String(description),
    "device": String(device),
    "label": String(label),
    "mark_connected": mark_connected,
    "maximum_draw": maximum_draw,
    "module": String(module),
    "name": String(name),
    "tags": tags,
    "type": String(type),
};
  bp.log.info("REQ PUT " + url + " Body: " + JSON.stringify(body));
  let res = svc.put(url, { body: JSON.stringify(body), expectedResponseCodes: [200], parameters: { description: reqDescription } });
  if (res.status >= 200 && res.status < 300) {
    bp.sync({ request: bp.Event("Done: Positive: " + reqDescription, {"allocated_draw": allocated_draw, "custom_fields": custom_fields, "description": description, "device": device, "id": id, "label": label, "mark_connected": mark_connected, "maximum_draw": maximum_draw, "module": module, "name": name, "tags": tags, "type": type}) });
  }
  return res;
}

