function verifyDashboardExists(config, id, layout) {
  // Fallback: Use list operation to verify existence
  let res = extras_dashboard_retrieve(config, id, layout);
  try {
      let listData = res;
      if (typeof listData === "string") listData = JSON.parse(listData);
      if (!Array.isArray(listData) && listData.data) listData = listData.data;
      if (Array.isArray(listData)) {
          let found = listData.find(item => item.id == id || item.id == id);
          if (found) pvg.success("Dashboard found in list");
          else pvg.fail("Dashboard NOT found in list");
      }
  } catch (err) { bp.log.warn("Failed to parse list response: " + err); }
}

function verifyDashboardDeleted(config, id, layout) {
  // Fallback: Use list operation to verify deletion
  let res = extras_dashboard_retrieve(config, id, layout);
  try {
      let listData = res;
      if (typeof listData === "string") listData = JSON.parse(listData);
      if (!Array.isArray(listData) && listData.data) listData = listData.data;
      if (Array.isArray(listData)) {
          let found = listData.find(item => item.id == id || item.id == id);
          if (!found) pvg.success("Dashboard correctly not found in list");
          else pvg.fail("Dashboard still found in list (deletion failed)");
      }
  } catch (err) { bp.log.warn("Failed to parse list response: " + err); }
}

function verifyDashboardDoesNotExist(config, id, layout) { verifyDashboardDeleted(config, id, layout); }

function matchAnyDashboardAdded() {
  return bp.EventSet("Any Dashboard Added", function(e) {
      return e.name.startsWith("Done: Positive: Create Dashboard");
  });
}

function matchDeletedDashboard(config, id, layout) {
  return bp.EventSet("Delete Dashboard", function(e) {
      return e.name.startsWith("Done: Positive: Delete a list of dashboard objects.");
  });
}

