function verifyVLANsExists(id) {
  var url = "/api/ipam/vlans/" + id + "/";
  var description = "Verify VLANs " + id + " exists";
  svc.get(url, { expectedResponseCodes: [200], parameters: { description: description } });
  pvg.success("VLANs found");
}

function verifyVLANsDeleted(id) {
  var url = "/api/ipam/vlans/" + id + "/";
  var description = "Verify VLANs " + id + " deleted";
  svc.get(url, { expectedResponseCodes: [404], parameters: { description: description } });
  pvg.success("VLANs correctly deleted (404)");
}

function verifyVLANsDoesNotExist(id) { verifyVLANsDeleted(id); }

