function schema_retrieve() {
  var url = "/api/schema/";
  var reqDescription = "OpenApi3 schema for this API. Format can be selected via content negotiation. {id}";
  return svc.get(url, { parameters: { description: reqDescription }, expectedResponseCodes: [200] });
}

function verifySchemaExists(format, id, lang) {
  // Fallback: Use list operation to verify existence
  let res = schema_retrieve(format, id, lang);
  try {
      let listData = res;
      if (typeof listData === "string") listData = JSON.parse(listData);
      if (!Array.isArray(listData) && listData.data) listData = listData.data;
      if (Array.isArray(listData)) {
          let found = listData.find(item => item.id == id || item.id == id);
          if (found) pvg.success("Schema found in list");
          else pvg.fail("Schema NOT found in list");
      }
  } catch (err) { bp.log.warn("Failed to parse list response: " + err); }
}

function verifySchemaDeleted(format, id, lang) {
  // Fallback: Use list operation to verify deletion
  let res = schema_retrieve(format, id, lang);
  try {
      let listData = res;
      if (typeof listData === "string") listData = JSON.parse(listData);
      if (!Array.isArray(listData) && listData.data) listData = listData.data;
      if (Array.isArray(listData)) {
          let found = listData.find(item => item.id == id || item.id == id);
          if (!found) pvg.success("Schema correctly not found in list");
          else pvg.fail("Schema still found in list (deletion failed)");
      }
  } catch (err) { bp.log.warn("Failed to parse list response: " + err); }
}

function verifySchemaDoesNotExist(format, id, lang) { verifySchemaDeleted(format, id, lang); }

function matchAnySchemaAdded() {
  return bp.EventSet("Any Schema Added", function(e) {
      return e.name.startsWith("Done: Positive: Create Schema");
  });
}

function status_retrieve() {
  var url = "/api/status/";
  var reqDescription = "A lightweight read-only endpoint for conveying NetBox's current operational status. {id}";
  return svc.get(url, { parameters: { description: reqDescription }, expectedResponseCodes: [200] });
}

function verifyStatusExists(id) {
  // Fallback: Use list operation to verify existence
  let res = status_retrieve(id);
  try {
      let listData = res;
      if (typeof listData === "string") listData = JSON.parse(listData);
      if (!Array.isArray(listData) && listData.data) listData = listData.data;
      if (Array.isArray(listData)) {
          let found = listData.find(item => item.id == id || item.id == id);
          if (found) pvg.success("Status found in list");
          else pvg.fail("Status NOT found in list");
      }
  } catch (err) { bp.log.warn("Failed to parse list response: " + err); }
}

function verifyStatusDeleted(id) {
  // Fallback: Use list operation to verify deletion
  let res = status_retrieve(id);
  try {
      let listData = res;
      if (typeof listData === "string") listData = JSON.parse(listData);
      if (!Array.isArray(listData) && listData.data) listData = listData.data;
      if (Array.isArray(listData)) {
          let found = listData.find(item => item.id == id || item.id == id);
          if (!found) pvg.success("Status correctly not found in list");
          else pvg.fail("Status still found in list (deletion failed)");
      }
  } catch (err) { bp.log.warn("Failed to parse list response: " + err); }
}

