function users_config_retrieve() {
  var url = "/api/users/config/";
  var reqDescription = "An API endpoint via which a user can update his or her own UserConfig data (but no one else's). {id}";
  return svc.get(url, { parameters: { description: reqDescription }, expectedResponseCodes: [200] });
}

function verifyUserConfigExists(id) {
  // Fallback: Use list operation to verify existence
  let res = users_config_retrieve(id);
  try {
      let listData = res;
      if (typeof listData === "string") listData = JSON.parse(listData);
      if (!Array.isArray(listData) && listData.data) listData = listData.data;
      if (Array.isArray(listData)) {
          let found = listData.find(item => item.id == id || item.id == id);
          if (found) pvg.success("UserConfig found in list");
          else pvg.fail("UserConfig NOT found in list");
      }
  } catch (err) { bp.log.warn("Failed to parse list response: " + err); }
}

function verifyUserConfigDeleted(id) {
  // Fallback: Use list operation to verify deletion
  let res = users_config_retrieve(id);
  try {
      let listData = res;
      if (typeof listData === "string") listData = JSON.parse(listData);
      if (!Array.isArray(listData) && listData.data) listData = listData.data;
      if (Array.isArray(listData)) {
          let found = listData.find(item => item.id == id || item.id == id);
          if (!found) pvg.success("UserConfig correctly not found in list");
          else pvg.fail("UserConfig still found in list (deletion failed)");
      }
  } catch (err) { bp.log.warn("Failed to parse list response: " + err); }
}

function verifyUserConfigDoesNotExist(id) { verifyUserConfigDeleted(id); }

function matchAnyUserConfigAdded() {
  return bp.EventSet("Any UserConfig Added", function(e) {
      return e.name.startsWith("Done: Positive: Create UserConfig");
  });
}

