function verifyWirelessLinksExists(id) {
  var url = "/api/wireless/wireless-links/" + id + "/";
  var description = "Verify WirelessLinks " + id + " exists";
  svc.get(url, { expectedResponseCodes: [200], parameters: { description: description } });
  pvg.success("WirelessLinks found");
}

function verifyWirelessLinksDeleted(id) {
  var url = "/api/wireless/wireless-links/" + id + "/";
  var description = "Verify WirelessLinks " + id + " deleted";
  svc.get(url, { expectedResponseCodes: [404], parameters: { description: description } });
  pvg.success("WirelessLinks correctly deleted (404)");
}

function verifyWirelessLinksDoesNotExist(id) { verifyWirelessLinksDeleted(id); }

function matchAnyWirelessLinksAdded() {
  return bp.EventSet("Any WirelessLinks Added", function(e) {
      return e.name.startsWith("Done: Positive: Post a list of wireless link objects.");
  });
}

